<?php session_start();if(!isset($_SESSION["studentsid"])){header("Location: ../index.php?msg=Please+log+in+as+Student");exit();}require_once __DIR__.'/../includes/db.php';$db=new db();$db->setconnection();$conn=$db->getConnection();$studentID=$_SESSION["studentsid"];$isbn=trim($_POST['isbn']??'');$bookTitle=trim($_POST['bookTitle']??'');if($isbn===''||$bookTitle===''){header("Location: student_dashboard.php?msg=Please+fill+in+fields");exit;}$stmt=$conn->prepare("INSERT INTO requests(student_id,isbn,book_name,status) VALUES(?,?,?,'pending')");$stmt->bind_param("sss",$studentID,$isbn,$bookTitle);$ok=$stmt->execute();$stmt->close();$db->closeConnection();header("Location: student_dashboard.php?msg=".($ok?"Request+submitted":"Error+submitting+request"));exit();?>